;!function(){try { var e="undefined"!=typeof globalThis?globalThis:"undefined"!=typeof global?global:"undefined"!=typeof window?window:"undefined"!=typeof self?self:{},n=(new e.Error).stack;n&&((e._debugIds|| (e._debugIds={}))[n]="32858c1a-5146-b2c9-0a37-4f70d557a660")}catch(e){}}();
(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,956713,e=>{"use strict";var t=e.i(168819);let a="xmas-presents",o="xmas-app",n="reward-tickets",s="speed-pass",i="blue-coupon",r="trial-switch",d="stack-deal",h="compact-phone",l="cancel-flow",c="profile-questions",u="chart-look",p="share-periods",m="download-ring",y="share-format",g="card-glass",w="look-live",f="custom-theme",b="member-tour",k="fee-scratch",v="mods",S="originals-5",A="share-pics",P=[{id:v,href:"/settings",added:"2026-11-26",quiet:!0,title:(0,t.msg)("Mods"),line:(0,t.msg)("Make members mods in Secret menu > Members > Mods. They get a Mod menu in Settings: reports, appeals, member lookup, bans and timeouts, notes, chats, the Mod log and stats, the word filter, and a MOD badge they can wear.")},{id:w,href:"/dashboard",added:"2026-11-25",title:(0,t.msg)("Real preview and true Clear"),line:(0,t.msg)("Appearance shows your real page while you change it, any page you pick. Cards and keys at Clear are fully see-through: no colour, no blur, only their edge.")},{id:f,href:"/dashboard",added:"2026-11-25",title:(0,t.msg)("Custom theme"),line:(0,t.msg)("Appearance > Themes has a Custom row under the four themes: pick your own colour for the outside, the page and the cards, with or without a background. Custom > Glass is now Layers.")},{id:g,href:"/dashboard",added:"2026-11-25",title:(0,t.msg)("Clearer glass cards"),line:(0,t.msg)("With a background and Liquid cards on a dark theme: Clear is really see-through, the cards are one clean colour with no lines, and your own card colour shows at full strength.")},{id:"study-mini-move",href:"/study",added:"2026-11-24",title:(0,t.msg)("Move and size the Mini video"),line:(0,t.msg)("In the Study Room, hold the thin bar on top of the Mini player to move it anywhere in the room, and pull its corner to make it bigger or smaller. It stays where you leave it, on every device.")},{id:"member-clock",href:"/settings?section=profile",added:"2026-11-24",title:(0,t.msg)("Every trade in your time zone"),line:(0,t.msg)("Synced trades used New York time, so a late trade could land on the wrong day. Now every trade, old ones too, shows in the Timezone from Settings > Profile. Same moments, your clock.")},{id:"careers",href:"/careers",added:"2026-11-23",quiet:!0,title:(0,t.msg)("Hiring: the application page"),line:(0,t.msg)("liquidjournal.app/careers opens to everyone: ten short questions, one at a time, saved as they type. Email, WhatsApp and Instagram to reach them, a how-bad-do-you-want-it slider, the flaw question marked Most important. Every application lands in Admin > Applications and in your mail.")},{id:"links-v2",href:"/links/preview",added:"2026-11-23",quiet:!0,title:(0,t.msg)("The new /links page"),line:(0,t.msg)("Our bio page keeps its look (moving liquid, the big Ring, the plan pills) with less text: the hiring card with two running lines under Start free, Replica and MT on top as trusted partners, shorter firm codes.")},{id:"study-pics",href:"/study",added:"2026-11-26",title:(0,t.msg)("Pictures on Study notes"),line:(0,t.msg)("Every note in a Study Room list shows a picture on the left: the trade's screenshot, a small chart of the trade, or the video's frame. Point at it for a bigger view; click it to upload, paste or pick your own."),announce:{heading:"Pictures on your Study notes",body:"Each note in the Study Room list now shows its trade or video on the left. Point at the picture to see it bigger, click it to put your own there."}},{id:"study-trash",href:"/study",added:"2026-11-23",title:(0,t.msg)("A trash can on Study notes"),line:(0,t.msg)("Every note in a Study Room list has a trash can: it shows on hover, always on a phone, and asks before it deletes. The Delete note line inside a note is gone."),announce:{heading:"Delete a note from the list",body:"Every note in the Study Room list now has a trash can. Hover a note to see it (on a phone it is always there). It asks before it deletes."}},{id:"credit-pack-250",href:"/dashboard",added:"2026-11-23",title:(0,t.msg)("A bigger credit pack"),line:(0,t.msg)("Buying AI credits now offers two packs: 100 credits for $5 or 250 credits for $10."),announce:{heading:"A bigger AI credit pack",body:"Apex can now buy 250 AI credits for $10, next to 100 for $5. Pick the pack in checkout."}},{id:a,href:"/dashboard",added:"2026-11-23",title:(0,t.msg)("Daily presents and the Shop"),line:(0,t.msg)("From 1 to 25 Dec a present waits at the top of your Dashboard every day. Untie it for plan days, a discount, points or an avatar decoration. Open 7 days in a row for a gold present. Your decorations live in Presents in Community's left bar, and the Shop below it sells more for points.")},{id:o,href:"/dashboard",added:"2026-11-23",title:(0,t.msg)("Christmas in the journal"),line:(0,t.msg)("Until 25 Dec: a pine garland on the top bar, a Santa hat on the Ring and snow on the Dashboard that piles up at the bottom. Sweep the pile off with the pointer. Turn it off in Appearance, next to the themes."),announce:{heading:"Snow in your journal",body:"Until 25 Dec you get a pine garland on the top bar, a Santa hat on the Ring and snow on your Dashboard. The snow piles up at the bottom of the screen. Move your pointer across the pile to sweep it off, or swipe it on a phone. Turn it off in Appearance, next to the themes."}},{id:"bg-feed",href:"/journal",added:"2026-11-22",title:(0,t.msg)("Background Feed for share cards"),line:(0,t.msg)("The Background tab has three parts: Feed (everyone's published backgrounds, search a name, a tag or @member), Liquid (ours) and Yours. Publish your own with a name and tags, save others into Yours, bookmark favorites. Essential holds 8, Prestige 20, Apex 50."),announce:{heading:"Share backgrounds from other members",body:"The Background tab in the share window now has a Feed. Search a name, a tag or a member, put a background on your card in one tap, save a copy into Yours or bookmark it. Publish your own with a name and up to three tags. Essential holds 8 backgrounds, Prestige 20 and Apex 50."}},{id:m,href:"/journal",added:"2026-11-22",title:(0,t.msg)("A ring while it saves"),line:(0,t.msg)("Save a video or GIF from the share window: a blue ring in the middle of the card counts from 1 to 100, then turns into a check for 2.5 seconds with a soft ting. Once in 1,000 saves the ting is the legendary fart, with a gold line to say so.")},{id:y,href:"/journal",added:"2026-11-22",title:(0,t.msg)("The card's format above the card"),line:(0,t.msg)("The share window names the card's format under Trade, Daily, Weekly and Monthly, with a small arrow to pick another. Weekly and Monthly start on P&L only, Trade and Daily on the line card, and each tab keeps your last pick.")},{id:b,href:"/dashboard",added:"2026-11-23",title:(0,t.msg)("One tour for new members"),line:(0,t.msg)("A new member gets one tour, no Beginner or Advanced question: the journal, sharing, the 5 free connectors, strategies, Showcase, prop firms, guardrails, Community, the link page and Appearance, ending on Study. New tour pictures, no ring on the card's button, the theme pick clear of the iPhone clock.")},{id:p,href:"/journal",added:"2026-11-22",title:(0,t.msg)("Day, week and month cards in Horizon"),line:(0,t.msg)("Share a day, a week or a month in the calmer Horizon look: the week as one bar per day, the month as your running P&L over each day's bar or as a calendar, the day's trades as a clean list. Origin under the picture keeps today's cards.")},{id:"share-studio",href:"/journal",added:"2026-11-22",title:(0,t.msg)("A calmer trade card"),line:(0,t.msg)("Share a trade: the card has no glow behind the number, lighter weights, Net P&L over it and the R under it, Entry, Exit and Size in one row, and a thinner line. Horizon is picked; Origin under the picture brings back today's card.")},{id:"your-songs",href:"/points",added:"2026-11-22",title:(0,t.msg)("Your songs"),line:(0,t.msg)("Appearance and your link page keep every song you add, one below the other: tap one to play it again, the pencil renames it, the x deletes it. Appearance keeps as many as your backgrounds, the link page the last 6.")},{id:u,href:"/journal",added:"2026-11-21",title:(0,t.msg)("Your own chart look"),line:(0,t.msg)("Set the Liquid chart your way: candle bodies, borders and wicks for up and down, the background, grid and scales, with Liquid, Classic and Mono templates or your own. A button opens the chart full screen.")},{id:c,href:"/dashboard",added:"2026-11-20",quiet:!0,title:(0,t.msg)("Two questions about your trading"),line:(0,t.msg)("Sign-up asks whether you trade prop firm accounts or your own money, and for how long. Members who joined before see one small card on the Dashboard, two taps, with Skip.")},{id:"welcome-screen",href:"/dashboard?welcome",added:"2026-11-20",title:(0,t.msg)("Welcome screen"),line:(0,t.msg)("Opening the journal greets you by name in your theme, then fades into your page. A tap skips it, and Settings can switch it off."),announce:{heading:"A welcome when you open Liquid",body:"Opening Liquid now greets you by name for a moment, in your own theme, then fades into your journal. Tap anywhere to skip it, or switch it off in Settings, under Preferences."}},{id:l,href:"/settings?section=subscription",added:"2026-11-20",title:(0,t.msg)("Cancel plan in the app"),line:(0,t.msg)("Billing asks why before a plan is cancelled and offers 60% off the next month once. The plan ends when the paid time is over, and Keep my plan undoes it."),announce:{heading:"Cancel a plan inside Liquid",body:"You can now cancel a plan in Settings, under Billing, without leaving Liquid. Your plan stays until the end of the time you paid for, and Keep my plan brings it back with one tap."}},{id:"multi-pick",href:"/dashboard",added:"2026-11-20",title:(0,t.msg)("Pick several accounts"),line:(0,t.msg)("Tap the circles in Total P&L to add accounts, groups or strategies together, like 3 of your 4 prop accounts. Journal, Analytics, Weekly and Strategy pick the same way."),announce:{heading:"Pick several accounts at once",body:"Tap Total P&L on the Dashboard, then the circle beside each account you want: 3 of your 4 prop accounts, a live account with a stack, or a strategy on top. The time switch works on whatever you picked, and the star opens the dashboard on it. Journal, Analytics, Weekly and Strategy pick the same way."}},{id:h,href:"/dashboard",added:"2026-11-19",title:(0,t.msg)("Compact phone"),line:(0,t.msg)("On phones and foldables: a slimmer bottom bar, the Dashboard numbers in one card on a foldable, a smaller total P&L and a shorter chart. Tablets and computers stay the same.")},{id:"flat-buttons",href:"/dashboard",added:"2026-11-17",title:(0,t.msg)("Flat buttons"),line:(0,t.msg)("Appearance > Buttons has a new look at the bottom, Flat: one flat tone, no light on top, no edge, no shadow, and nothing moves. On Midnight and Onyx the buttons are dark on dark.")},{id:"tradovate-off",href:"/dashboard?wallet=connect",added:"2026-11-17",title:(0,t.msg)("Switch Tradovate accounts off"),line:(0,t.msg)("A Tradovate login syncs every account on it. Accounts that sync now has a switch per account: off keeps its new trades out of your journal."),announce:{heading:"Pick which Tradovate accounts sync",body:"Your Tradovate card now lists every account on the login with a switch. Switch one off and its new trades stay out of your journal; trades already in it stay."}},{id:"save-email",href:"/settings?section=subscription",added:"2026-11-18",title:(0,t.msg)("Failed payment email"),line:(0,t.msg)("When a renewal fails twice, the member gets one email: pay with another card, or keep the journal free on Essential. Until you push, each one comes to you instead."),quiet:!0},{id:"share-plan-2",href:"/daily",added:"2026-11-18",title:(0,t.msg)("Share your plan, with a chart"),line:(0,t.msg)("Share on a saved plan: switches change the card quietly, Save picture makes it, and your chart picture can go on it, small or big."),quiet:!0},{id:"life-log",href:"/daily",added:"2026-11-17",title:(0,t.msg)("Life log in the Daily"),line:(0,t.msg)("The plan gets a Life card: sleep, mood, energy, exercise and your own habits. Analytics and the AI coach show which days you trade better."),announce:{heading:"Log your sleep, mood and habits",body:"Your Daily plan now has a Life card: scroll to the hours you slept, grade your mood, drag your energy, tick exercise and your own habits. Analytics then shows which days you trade better, and the AI coach uses it in its answers."}},{id:d,href:"/dashboard",added:"2026-11-17",title:(0,t.msg)("Copy groups deal out"),line:(0,t.msg)("On the Desk, Show on a copy-trade group slides its accounts down out of the stack one by one. Hide puts them back."),announce:{heading:"Copy groups open one by one",body:"On the Desk, tap Show on a copy-trade group: its accounts now slide down out of the stack one after another instead of appearing all at once. Hide puts them back into the stack."}},{id:"cal-grow",href:"/dashboard",added:"2026-11-21",title:(0,t.msg)("One calendar shape on every screen"),line:(0,t.msg)("The P&L calendar on the Dashboard and in Analytics keeps the same wide day on every screen, from a phone to a big monitor, with tight gaps. A bigger screen makes the days taller too.")},{id:"money-foot",href:"/dashboard",added:"2026-11-21",title:(0,t.msg)("Coloured edges under wins"),line:(0,t.msg)("In Liquid Horizon on Light and Platinum, the edge under a win day, a win bar and the week's capsules is a darker shade of its own colour instead of black.")},{id:"metal-accents",href:"/dashboard",added:"2026-11-17",title:(0,t.msg)("Metallic accents"),line:(0,t.msg)("Appearance > Accent has twelve metallic colours above the flat ones: Liquid blue, Black, Pearl, Silver, Gold, Bronze, Orange, Ruby, Jade, Teal, Ice and Rose gold. Community wears your accent too."),announce:{heading:"Twelve metallic accents",body:"Appearance > Accent now has a Metallic row above the flat colours: Liquid blue, Black, Pearl, Silver, Gold, Bronze, Orange, Ruby, Jade, Teal, Ice and Rose gold. Pick one and your accent wears that metal and its light. Community follows your accent too: its tab line, links, tags, unread counts and story rings. Open it from your account picture: Appearance, then Accent."}},{id:"look-picker",href:"/dashboard",added:"2026-11-18",title:(0,t.msg)("The look picker"),line:(0,t.msg)("Pick Liquid Origin or Liquid Horizon on one screen: two windows that play each page arriving, in your own theme. It opened once by itself; open it again with Show the picker.")},{id:"email-change",href:"/settings?section=profile",added:"2026-11-16",title:(0,t.msg)("Change your email"),line:(0,t.msg)("Settings > Profile > Email > Change moves your whole account to a new address: sign-in, receipts and every Liquid email."),announce:{heading:"You can change your email now",body:"Open Settings > Profile and choose Change next to your email. Type the new address and your password, then the code we send to the new inbox. Your journal, plan and receipts move with you, and you sign in with the new address from then on."}},{id:"free-locks",href:"/dashboard",added:"2026-11-16",title:(0,t.msg)("Locked features as a preview"),line:(0,t.msg)("On Essential, a locked feature shows itself blurred with your own numbers, and one Unlock button on top.")},{id:"coach-notes",href:"/study",added:"2026-11-16",title:(0,t.msg)("Coach answers as notes"),line:(0,t.msg)("Save a coach answer to Study and it reads like the coach, links to your trades included. Type / and pick Link trade to link your own words.")},{id:r,href:"/#pricing",added:"2026-11-15",title:(0,t.msg)("Trial or pay today"),line:(0,t.msg)("Monthly checkout offers 10 days free or Pay today, side by side. Pay today brings PayPal back.")},{id:i,href:"/#pricing",added:"2026-11-15",title:(0,t.msg)("Blue coupon at checkout"),line:(0,t.msg)("A code that is on shows as the website's blue ticket. A free code says 100% off.")},{id:"smooth-bubble",href:"/dashboard",added:"2026-11-15",title:(0,t.msg)("Smooth theme change"),line:(0,t.msg)("Changing a theme or colour: the new look sweeps across the page instead of the circle that lagged."),announce:{heading:"A smoother theme change",body:"When you change your theme or colour, the new look now sweeps across the page from left to right. It replaces the growing circle, which lagged in Safari and on iPhone."}},{id:"trials",href:"/#pricing",added:"2026-11-15",title:(0,t.msg)("10-day free trial"),line:(0,t.msg)("New members try Prestige or Apex free for 10 days, then pay. The pricing buttons say Try free."),announce:{heading:"Try Prestige or Apex free for 10 days",body:"New to a paid plan? Try Prestige or Apex free for 10 days. You add a card at the start and pay nothing until day 10. We email you the day before, and you can cancel any time in Billing."}},{id:"quick-tabs",href:"/dashboard",added:"2026-11-15",title:(0,t.msg)("Quick bottom bar"),line:(0,t.msg)("On a phone the tab lights the moment you touch it, and the new page shows sooner. Same slide."),announce:{heading:"A quicker bottom bar",body:"On your phone, a tab in the bottom bar now lights up the moment you touch it, and the next page shows sooner. The slide between pages stays the same."}},{id:"smooth-entrance",href:"/journal",added:"2026-11-15",title:(0,t.msg)("Smoother page openings"),line:(0,t.msg)("In Safari the Journal cards open without the stutter while the numbers count up. Same animation."),announce:{heading:"Smoother Journal in Safari",body:"The Journal cards and their numbers now open smoothly in Safari. The animation is the same, without the stutter."}},{id:s,href:"/community",added:"2026-11-15",quiet:!0,title:(0,t.msg)("Faster Community opening"),line:(0,t.msg)("Community opens in order, left to right, once its pictures are ready, and draws the rest of the posts before you scroll to them. Same look.")},{id:"no-tradovate-logo",href:"/settings?s=connect",added:"2026-11-15",quiet:!0,title:(0,t.msg)("No Tradovate logo"),line:(0,t.msg)("Tradovate and NinjaTrader are named in words only: no logo on Connect, broker tiles, the dashboard nudge, Links or the website.")},{id:"ai-feel",href:"/ai",added:"2026-11-13",title:(0,t.msg)("The AI writes itself in"),line:(0,t.msg)("Every new answer blurs in word by word, like the website. The one thing that matters most is marked in purple, key points are bold, and links glide."),announce:{heading:"The AI feels new",body:"Answers now write themselves in word by word, with the soft blur from our website.\n\nThe thing that matters most in an answer is marked in purple, the key points are bold, and the asides are quieter, so you can read an answer at a glance. Links in an answer move smoothly when you point at them."}},{id:"cm-report",href:"/community",added:"2026-11-13",title:(0,t.msg)("A deeper Report"),line:(0,t.msg)("Report asks what is wrong in 3 short steps. Two scam or promotion reports hide the post until LIQUID looks."),announce:{heading:"Report now asks what is wrong",body:"Report on a Community post now takes 3 short steps: what is wrong, what exactly, and where. LIQUID sees the full picture and acts faster.\n\nTwo reports of a scam or a promotion hide the post until LIQUID looks."}},{id:n,href:"/points",added:"2026-11-13",quiet:!0,title:(0,t.msg)("New reward tickets"),line:(0,t.msg)("The Prestige and Apex months on Points as the website ticket, in gold and purple.")},{id:"community-points",href:"/community",added:"2026-11-13",title:(0,t.msg)("Spam slowdown"),line:(0,t.msg)("Posting the same words again and again, or a burst of posts, slows you down for a few minutes. Messages and likes still work."),announce:{heading:"A smarter spam filter in Community",body:'Posting the same words again and again, or a burst of posts in a row, now slows you down for a few minutes. Normal back and forth never counts, and messages and likes always work.\n\nIf it ever slows you down by mistake, tap "This was a mistake" and LIQUID will look.'}},{id:"study-video-list",href:"/study",added:"2026-11-13",title:(0,t.msg)("Several videos in one note"),line:(0,t.msg)("Keep up to 10 YouTube, Loom or Vimeo videos in a note and tap one to play it. Every time in the note jumps to its own video."),announce:{heading:"Several videos in one Study note",body:"A note can now hold up to 10 videos. Add the next lesson under the player and tap any of them to watch it; nothing is deleted to switch, and only one plays at a time.\n\nEvery time you take is kept with its own video, so tapping a time from another video opens that video at that moment. Rename, reorder or remove videos from the pencil on each one."}},{id:"study-video-links",href:"/study",added:"2026-11-13",title:(0,t.msg)("Loom and Vimeo in Study"),line:(0,t.msg)("Paste a Loom or Vimeo link wherever a YouTube link works: a note's video, the note itself, or a board. Times in the note jump the video."),announce:{heading:"Loom and Vimeo videos in the Study Room",body:"Your notes are not only for YouTube any more. Paste a Loom or Vimeo link as a note's video, straight into the note, or onto a board, and write while it plays.\n\nOn Vimeo every time in your note jumps the video, just like YouTube. On Loom a time opens the video at that moment. Shared notes and boards play them too."}},{id:"copier-merge",href:"/propfirm",added:"2026-11-12",title:(0,t.msg)("Copies become one trade"),line:(0,t.msg)("Copies your copier sends to a copy-trade group fold into one trade. Each account keeps its own size and P&L, and Split puts them back."),announce:{heading:"Copied trades are one trade now",body:"If you copy trade, the copies your broker sync brings in for the accounts of one copy-trade group now become one trade. Each account keeps its own size and P&L, and the total is their sum. Open a trade and tap Split to put them back, or turn Merge copies off for a group in Prop accounts > Copy trade."}},{id:"copy-sizes",href:"/propfirm",added:"2026-11-14",title:(0,t.msg)("Copy trade sizes"),line:(0,t.msg)("Give each account in a copy group its own size. The total P&L you log splits by size, so a 2x account gets twice the share."),announce:{heading:"Copy groups know your sizes",body:"If one of your copied accounts trades bigger than the leader, give it a size in Prop accounts > Copy trade: 0.5x, 2x, 3x or any number from 0.1 to 10. The total P&L you log now splits by size, so each account's balance and drawdown stay right. Change a size and we ask once whether past trades should follow."}},{id:"tradelocker-sync",href:"/dashboard?wallet=connect",added:"2026-11-13",title:(0,t.msg)("TradeLocker fills your journal"),line:(0,t.msg)("Sign in to TradeLocker once in Wallet > Connect. Every closed trade lands in your journal by itself, free on every plan."),announce:{heading:"TradeLocker now syncs to Liquid",body:"Connect TradeLocker once and your forex and CFD prop trades log themselves. It's free on every plan.\n\nGo to Wallet, then Connect, and sign in with your TradeLocker email, password and server. Your last 30 days come in when you connect, and each TradeLocker account goes into the journal account you pick.\n\nTradeLocker sends no fees or swaps, so a trade's P&L comes in before them. The connection only reads your trades. It can't place, change or cancel an order.\n\nLiquid is an independent journal, not made or endorsed by TradeLocker."}},{id:"topstepx-guide",href:"/dashboard?wallet=connect",added:"2026-11-12",title:(0,t.msg)("TopstepX setup, step by step"),line:(0,t.msg)("The TopstepX card in Wallet > Connect walks you through it: the ProjectX account, API Access, linking, your key, then connect. Pictures from TopstepX on the steps."),announce:{heading:"TopstepX now syncs to Liquid",body:"Connect TopstepX once and your Topstep trades log themselves, fees included. It's free on every plan.\n\nGo to Wallet, then Connect, and tap Set up TopstepX. The card walks you through five steps with pictures: make your ProjectX account, turn on API Access, link it in TopstepX, make your key and paste it. Leave to get the key and you come back to the same step.\n\nThe connection only reads your trades. It can't place, change or cancel an order. Your last 30 days come in when you connect, and each TopstepX account, evaluation or funded, goes into the journal account you pick.\n\nLiquid is an independent journal, not made or endorsed by Topstep."}},{id:"liquid-look",href:"/dashboard",added:"2026-11-11",title:(0,t.msg)("The LIQUID look"),line:(0,t.msg)("The journal's pieces redrawn: a ring of ticks for the win rate, rulers, pills, raised calendar keys, and buttons that press down onto their foot, with one blue key a page. Pick New below to try it on this device.")},{id:"share-inter",href:"/journal",added:"2026-11-11",title:(0,t.msg)("Share cards look the same on every device"),line:(0,t.msg)("Share cards draw the P&L, the stats and the rest of the card in one font on every phone and computer, so a card made on Windows looks like one made on an iPhone."),announce:{heading:"Share cards look the same on every device",body:"Your share cards now use one font everywhere. A card made on Windows, Android or Opera used to come out thinner than one made on an iPhone. Now the P&L and the stats look the same whoever makes the card, in photos and in videos."}},{id:"set-password",href:"/settings?section=profile",added:"2026-11-11",title:(0,t.msg)("A password for Google accounts"),line:(0,t.msg)("Signed up with Google or Apple? Settings > Profile can now email you a link to set a password, then you sign in with your email or @username too."),announce:{heading:"Add a password to a Google account",body:"Signed up with Google or Apple? You can now add a password. Open Settings > Profile, choose Set a password under your email, and open the link we send you. Then you can sign in with your email or your @username and that password. Google keeps working too."}},{id:"replica-banner",href:"/dashboard?wallet=connect",added:"2026-11-11",title:(0,t.msg)("Replica banner"),line:(0,t.msg)("Replica's own banner on top of their card in Connect, with Connect and Visit under it.")},{id:"month-session",href:"/journal",added:"2026-11-12",title:(0,t.msg)("Month filter and session no-trade"),line:(0,t.msg)("Pick one month in the Journal filters. A no-trade entry can belong to one session and shows in that session's journal."),announce:{heading:"Pick a month, sit out one session",body:"Journal filters now have a Month box: pick July and you see only July. A No Trade entry that says Followed rules or Missed trade can belong to one session, so it lands in that session's journal and still shows in the day. Analytics counts the day once."}},{id:"typed-balance",href:"/propfirm",added:"2026-11-12",title:(0,t.msg)("Typed balance check"),line:(0,t.msg)("Log a trade dated on or before a balance you typed and Liquid asks if it is already in it. The account window shows the typed part with Remove.")},{id:"long-prompts",href:"/dashboard",added:"2026-11-11",title:(0,t.msg)("Long prompts and notes"),line:(0,t.msg)("Paste up to 5,000 words into any AI box. Ask the bot to make it a Study note and pick the folder, or save an answer as a note."),announce:{heading:"Paste a whole page to the AI",body:"Every AI box in Liquid now takes up to 5,000 words: the bot, the Study Assistant, Study AI and the Prop Firms AI. Paste your notes, a transcript or a plan and ask the bot to make it a Study note. It keeps every point, puts the key takeaways on top, and asks which folder it goes in, or makes a new one. Coach and Study answers have a Save as note button too."}},{id:"fee-net",href:"/journal",added:"2026-11-11",title:(0,t.msg)("Fees off P&L"),line:(0,t.msg)("Type a fee on a trade and Liquid offers the P&L after it, Use or Keep mine. A minus sign or a comma works.")},{id:"wide-layout",href:"/dashboard",added:"2026-11-11",title:(0,t.msg)("Wide layout"),line:(0,t.msg)("Fold the Desk and the Plan on a big screen and pages spread out: four across on the dashboard, more trades per row on Showcase."),announce:{heading:"A wider journal",body:"Fold the Desk and the Plan on a big screen and Liquid uses the room. The dashboard goes four across with Score & Psychology and this week's goal beside your Liquid Score, the calendar and the news sit side by side, Showcase shows four or five trades a row, and Analytics puts its smaller cards next to each other. Open a rail again and everything goes back. Nothing to set."}},{id:"goal-deadlines",href:"/dashboard",added:"2026-11-13",title:(0,t.msg)("Goal deadlines"),line:(0,t.msg)("Give any goal a deadline: a day this week, this month or this year, or any day for your lifetime goal. The card counts down and asks when it passes."),announce:{heading:"Deadlines on your goals",body:"Open Edit on your goals and give any of them a deadline. A weekly, monthly or yearly goal takes a day inside its period; your lifetime goal takes any day you choose. The card counts the days down, and when the deadline passes Liquid asks if you got there."}},{id:"account-drag",href:"/dashboard",added:"2026-11-13",title:(0,t.msg)("Move your accounts"),line:(0,t.msg)("Drag an account by its mark to put the Desk in your own order. Your order follows you to every device."),announce:{heading:"Put your accounts in your order",body:"On the Desk, hold an account by its mark and drag it up or down. Prop firms, Live and Other each keep their own order, and it follows you to every device."}},{id:"life-goals",href:"/dashboard",added:"2026-11-10",title:(0,t.msg)("Goals that are not money"),line:(0,t.msg)("Above the calendar: a goal for this week, this month, this year and your life, the steps to get there, and a picture of your why."),announce:{heading:"Goals that are not money",body:"The goals above your calendar are now about what you want to reach, not a dollar number. Set one for this week, this month, this year and your life, add up to three steps for each, and put a picture of your why behind them: the car, the house, the place. Only you see them. When a week or month ends, Liquid asks if you got there."}},{id:"mfe-r",href:"/settings?section=preferences",added:"2026-11-10",title:(0,t.msg)("MFE and MAE in R"),line:(0,t.msg)("Type and read MFE and MAE in R instead of dollars. Switch it in Settings > Preferences."),announce:{heading:"MFE and MAE in R",body:"You can now type and read MFE and MAE in R instead of dollars. Turn it on in Settings > Preferences: 1R is your stop, and Liquid works out the dollars for you. A trade with no stop keeps showing dollars."}},{id:"share-entry",href:"/daily",added:"2026-11-10",title:(0,t.msg)("Share your bias"),line:(0,t.msg)("Your plan as a picture: the bias big, your levels and scenarios under it. No P&L.")},{id:"analytics-streaks",href:"/analytics",added:"2026-11-09",title:(0,t.msg)("Win streak, loss streak, expectancy"),line:(0,t.msg)("Three more numbers at the top of Analytics, under the first six.")},{id:"more-pictures",href:"/journal",added:"2026-11-09",title:(0,t.msg)("More pictures on a trade"),line:(0,t.msg)("A trade now holds 10 pictures on Prestige and 20 on Apex.")},{id:"flat-cards",href:"/dashboard",added:"2026-11-09",quiet:!0,title:(0,t.msg)("Plain dark cards"),line:(0,t.msg)("Dark cards are one plain colour, with no fade and no faint lines.")},{id:"flat-cards-all",href:"/analytics",added:"2026-11-10",quiet:!0,title:(0,t.msg)("Plain dark cards everywhere"),line:(0,t.msg)("Calendar days, insight cards and the Daily and Weekly cards lose their fade too, so no faint lines anywhere.")},{id:"chat-reactions",href:"/community",added:"2026-11-09",title:(0,t.msg)("Emoji reactions in chat"),line:(0,t.msg)("Hold a message in a DM or crew chat: the chat dims, six emojis sit above it, Reply and Copy below. Crew chat gets replies too.")},{id:"analytics-filters",href:"/analytics",added:"2026-11-08",title:(0,t.msg)("Filter by trade"),line:(0,t.msg)("Analytics > Filters: only longs or shorts, one trade type or strategy, and tap a ticker to hide it.")},{id:"photo-one-tap",href:"/journal",added:"2026-11-08",title:(0,t.msg)("Photo in one tap"),line:(0,t.msg)("The share window makes the Photo while it opens and after each change, so one tap saves it. Video backgrounds and 4K work as before.")},{id:"fees-total",href:"/analytics",added:"2026-11-08",title:(0,t.msg)("Total fees paid"),line:(0,t.msg)("Analytics > Habits: one card with all the commissions and fees on the trades in view, and the average per trade.")},{id:"insight-flip",href:"/analytics",added:"2026-11-08",title:(0,t.msg)("Insight cards that turn"),line:(0,t.msg)("Analytics > Insights: each pattern is one clean name on a black plate. Hover or tap and it turns over to show the numbers and what to do."),announce:{heading:"Insights, cleaner",body:"Each pattern in Analytics is one clean name now. Hover or tap a card and it turns over to show the numbers and what to do."}},{id:"news-share",href:"/dashboard",added:"2026-11-08",title:(0,t.msg)("Share the news"),line:(0,t.msg)("A Share button on the News card: the day or the week as a picture on your own background, Wide or Story, liquidjournal.app on top and your name if you want. Save it or post it to Community."),announce:{heading:"Share the news",body:"The News card has a Share button now. Make a picture of the day or the week on your own background, then save it or post it to Community."}},{id:"cursor-3d",href:"/dashboard",added:"2026-11-07",title:(0,t.msg)("3D cursor"),line:(0,t.msg)("The website's 3D arrow in the journal, always: white on dark, black on light, a soft ring when you click. Only text boxes keep the text cursor. Appearance > Cursor switches back to your normal one; a heads-up says so once."),announce:{heading:"A new cursor",body:"Your journal has a new 3D arrow: white on dark, black on light, with a soft ring when you click. Prefer your usual cursor? Appearance > Cursor switches it back."}},{id:"one-glass",href:"/points",added:"2026-11-09",title:(0,t.msg)("Every card the same glass"),line:(0,t.msg)("Links, Daily, Weekly and the last few cards now wear the same frosted glass as the Journal. The browser bar above your link page follows your theme.")},{id:"card-gaps",href:"/dashboard",added:"2026-11-09",title:(0,t.msg)("The same space between cards"),line:(0,t.msg)("Dashboard, Journal, Showcase and Strategy now keep the same small space between cards as Analytics. The cards grow into the room.")},{id:"link-page",href:"/points",added:"2026-11-07",title:(0,t.msg)("Your link page"),line:(0,t.msg)("liquidjournal.app/@username: your picture, socials, your own links and a Join button that credits you. Points is now Links, with a share button by the Wallet."),announce:{heading:"Your own link page",body:"Every member now has a page for their bio: your picture, your socials, your own links and a Join button that earns you points. Find it under Links."}},{id:"you-ask-1",href:"/dashboard",added:"2026-11-07",lasts:24,title:(0,t.msg)("You ask, we add: Mommy ASMR"),line:(0,t.msg)("A Don't click pill in the top bar opens Mommy ASMR, with a Keep it or Drop it vote. Push starts its 24 hours; then it goes for everyone on its own."),announce:{heading:"Day 1 of You ask, we add: Mommy ASMR, for one day",body:"Find the Don't click button at the top of your journal. Press it if you dare, then vote if it stays. It goes in 24 hours."}},{id:"analytics-sections",href:"/analytics",added:"2026-11-04",title:(0,t.msg)("Analytics sections"),line:(0,t.msg)("A centred section bar that keeps your section in view, big titles where each section starts, and Combos that pay first in Performance. Two looks to pick from: add ?sections=b for the second.")},{id:"review-pics",href:"/daily",added:"2026-11-07",title:(0,t.msg)("Pictures in your review"),line:(0,t.msg)("The post-market review takes chart pictures too, as many as your plan: how the day played out, your entries and exits."),announce:{heading:"Pictures in your review",body:"Your end-of-day review now takes chart pictures, like your plan. Add how the day played out, your entries and your exits."}},{id:"mail-translate",href:"/dashboard",added:"2026-11-09",title:(0,t.msg)("Translate in the Mailbox"),line:(0,t.msg)("Mailbox notes in another language get a Translate link into your app language. Always translate in Settings > Profile covers them too."),announce:{heading:"Read the Mailbox in your language",body:"Mailbox notes written in another language now have a Translate link. Turn on Always translate in Settings, Profile and they arrive translated."}},{id:"cm-format",href:"/community",added:"2026-11-21",title:(0,t.msg)("Formatting in Community posts"),line:(0,t.msg)("Posts and replies read Discord formatting: bold, italic, headings, quotes, lists, small footnotes and :emoji: codes. A preview shows under the box as you type."),announce:{heading:"Format your posts like on Discord",body:"Bold, headings, quotes, lists and :emoji: codes now show in Community posts. Paste from Discord and it keeps its look; a preview shows under the box as you type."}},{id:"cm-translate",href:"/community",added:"2026-11-06",title:(0,t.msg)("Translate in Community"),line:(0,t.msg)("Posts, replies, messages and crew chats in another language get a Translate button into your app language. Settings > Profile has Always translate."),announce:{heading:"Read Community in your language",body:"Posts, replies and messages written in another language now have a Translate button. Turn on Always translate in Settings, Profile."}},{id:"top-save",href:"/journal",added:"2026-11-04",title:(0,t.msg)("Save Changes from the top"),line:(0,t.msg)("Editing a trade, a big Save Changes slides down from the top once you change something, and steps away when the Save button at the bottom is in view."),announce:{heading:"Save without scrolling down",body:"When you edit a trade and change something, a Save Changes button now slides down at the top, so you can save without scrolling to the bottom."}},{id:"combos",href:"/analytics?section=performance",added:"2026-11-04",title:(0,t.msg)("Combos that pay"),line:(0,t.msg)("Under Confluences that pay: the chips you tick together, scored as one combo, with its win rate and what it makes a trade. The AI insights read your best and worst combos too.")},{id:"compare-wallet",href:"/propfirm",added:"2026-11-04",title:(0,t.msg)("Compare in the Wallet"),line:(0,t.msg)("Compare leaves Analytics. A small bar at the foot of your accounts, beside Compare payouts to spend, opens it.")},{id:"look-upgrade",href:"/dashboard",added:"2026-11-03",quiet:!0,title:(0,t.msg)("Upgraded look"),line:(0,t.msg)("Deeper blacks, cards that sit like raised plates, a pill top bar whose tabs light up, and pages that arrive in one calm wave, their charts and figures with them. Pick Current or Upgraded for this device.")},{id:"glass-steady",href:"/dashboard",added:"2026-11-03",title:(0,t.msg)("Steady glass"),line:(0,t.msg)("With your own picture, glass cards stay frosted while a page leaves and arrives, instead of showing the picture clear for a moment. The Cumulative P&L end dot is plain and a touch smaller."),announce:{heading:"Smoother pages on your picture",body:"With your own background picture, the glass cards now stay frosted while you move between pages. The end dot on Cumulative P&L is a little smaller and plain."}},{id:"cert-pct",href:"/propfirm",added:"2026-11-02",title:(0,t.msg)("Certificates in %"),line:(0,t.msg)("Certificates get a $ / % switch: a payout shows its share of the account, a funded pass its gain, on the wall, the moving rail and when you share one.")},{id:"recaps-settings",href:"/settings",added:"2026-11-02",title:(0,t.msg)("Recaps in Settings"),line:(0,t.msg)("Settings > Recaps lists every finished month and year you traded in, each with Play, on every plan. On Essential the X on the recap card points there."),announce:{heading:"Rewatch your recaps",body:"Every finished month and year now lives in Settings > Recaps. Tap Play on any of them, on every plan."}},{id:"share-text",href:"/journal",added:"2026-11-02",title:(0,t.msg)("Text on the share card"),line:(0,t.msg)("The share window gets a Text tab: one short line of yours on the card, in quotes above the footer, on the photo, GIF and video.")},{id:"plan-assets",href:"/daily",added:"2026-11-02",title:(0,t.msg)("Plan by asset"),line:(0,t.msg)("Trade more than one market? Add each asset to the day plan: its own bias, levels and scenarios. The Plan rail lists them all.")},{id:"custom-account",href:"/propfirm",added:"2026-11-02",title:(0,t.msg)("Custom account and Account missing?"),line:(0,t.msg)("Add account > Prop firm > Other: set your own firm's rules (max loss and how it trails, daily loss, target, days), or tell us which firm is missing.")},{id:"mac-size",href:"/dashboard",added:"2026-11-02",title:(0,t.msg)("Mac size on big screens"),line:(0,t.msg)("On an ultrawide or very big screen the whole app scales up together, so it looks like it does on a MacBook instead of small text stretched across the screen.")},{id:"links-coaching",href:"/links/preview",added:"2026-11-02",quiet:!0,title:(0,t.msg)("Liquid Coaching on /links"),line:(0,t.msg)("Our bio page shows Liquid Coaching second, right after the journal: the TPC bull, MT Trading One, Our trusted partner and Sign up for coaching.")},{id:"liquid-coaching",href:"/coaching",added:"2026-11-02",title:(0,t.msg)("Liquid Coaching"),line:(0,t.msg)("The Liquid Coaching tab takes Points' place in the top bar and opens MT Trading One's TPC card: his numbers, Sign up for coaching and more about TPC. Points stay on the pill beside your credits.")},{id:"nav-dock-2",href:"/dashboard",added:"2026-11-01",title:(0,t.msg)("New top bar"),line:(0,t.msg)("Pick the top bar this computer shows: v1 is today's tabs, v2 the notched bar, v3 icons with a sliding circle, v4 tabs with a sliding pill, v5 tabs with a raised tab that slides. Members keep v1.")},{id:"csv-merge",href:"/journal",added:"2026-10-31",title:(0,t.msg)("Merge while importing a CSV"),line:(0,t.msg)("In the CSV preview, Merge lets you pick the partials of one position and turn them into one trade before you import, by the same rules as Merge in the Journal."),announce:{heading:"Merge partials as you import",body:"Importing a CSV with partials or adds? Before you press Import, tap Merge, pick the rows that were one position and they come in as one trade: the P&L, fees and contracts added up, the average entry and exit, the first entry and the last exit."}},{id:"csv-export",href:"/journal",added:"2026-11-01",title:(0,t.msg)("Export your journal as a CSV"),line:(0,t.msg)("Wallet > CSV > Export: every trade you logged, one row each, with setups, confluences, prices, R and notes. Pick the accounts, the dates and the columns; for your own scripts or Excel."),announce:{heading:"Your journal, as a CSV",body:"Wallet > CSV > Export downloads every trade you logged, one row each: setups, confluences, entries, exits, stops, targets, R and notes. Pick accounts, dates and columns, then run it through your own scripts or open it in Excel."}},{id:"post-crop",href:"/community",added:"2026-11-01",title:(0,t.msg)("Crop pictures in a post"),line:(0,t.msg)("Tap a picture in New post to open it in the feed's frame: drag it, zoom in, and the post shows exactly that."),announce:{heading:"Frame your pictures",body:"In New post, tap a picture to crop it: drag it up, down or sideways and zoom in. The feed shows exactly what you framed."}},{id:"recap-card",href:"/dashboard",added:"2026-11-01",title:(0,t.msg)("Recap card on the dashboard"),line:(0,t.msg)("When a month ends, its recap waits on top of the dashboard on a frosted card until you play it or close it. Close it and it waits under this month's calendar; close that and it stays with its own month. The recap is free on every plan."),announce:{heading:"Your month, on top",body:"When a month ends, its recap now waits on top of your dashboard. Play it like a story, or close it and find it under the calendar. Every plan gets the recap now."}},{id:"share-blur",href:"/journal",added:"2026-10-31",title:(0,t.msg)("Blurred share background"),line:(0,t.msg)("The Share window no longer sits on black: the page behind it shows through, blurred. Dark on dark themes, white on the light theme, and it glides in instead of popping up."),announce:{heading:"Share, see through",body:"Open Share on a trade, a day or a certificate and the page behind stays in sight, softly blurred: dark on dark themes, white on the light one. The window glides in row by row instead of popping up."}},{id:"liquid-scrollbar",href:"/journal",added:"2026-10-31",title:(0,t.msg)("Liquid scrollbar"),line:(0,t.msg)("Everywhere in the app that had a scrollbar, the old bar is gone while you read. Scroll and a soft drop swells in and stretches with your speed; stop and it narrows and fades away. It takes your theme's colour."),announce:{heading:"A quieter scrollbar",body:"Across the app, the scrollbar now stays out of sight while you read. Scroll and a soft drop swells in, stretching a little with your speed. Stop, and it narrows and fades away."}},{id:"liquid-switch",href:"/settings?section=preferences",added:"2026-10-31",title:(0,t.msg)("Liquid switch"),line:(0,t.msg)("A fourth switch sound next to Blue, Brown and Red: Liquid, the crisp click from our new website. Pick it in Settings > Preferences or Appearance > Buttons > Sound. It plays on buttons and, with typing sounds on, as you type."),announce:{heading:"A new click: Liquid",body:"Next to Blue, Brown and Red there is a fourth switch sound now, Liquid: a short, crisp click. Pick it in Appearance, Buttons, Sound, or in Settings, Preferences. Turn on typing sounds to hear it as you write."}},{id:"dm-reply",href:"/community",added:"2026-10-30",title:(0,t.msg)("Reply to a message in DMs"),line:(0,t.msg)("In a chat, swipe a message right on a phone, or use the arrow beside it on a computer (or hold it, or right-click, then Reply). The reply quotes it; a tap on the quote jumps up to it. Needs migration 0106 to save the link."),announce:{heading:"Reply to one message",body:"In your messages, swipe a message to the right, or tap the arrow next to it, to answer that exact message. Tap the quote to jump back to it."}},{id:"delete-history",href:"/settings?section=delete-history",added:"2026-10-30",title:(0,t.msg)("Delete history"),line:(0,t.msg)("Settings > Account > Delete history: your question, Yes, then a last Yes. Every account or one; trades, Daily and Weekly entries and their pictures go on every device. A backup download sits on the first step; nothing is kept."),announce:{heading:"Start fresh when you need to",body:"You asked for it: Settings > Delete history wipes your trades, Daily and Weekly entries, or only one account's trades. Download a backup first, because nothing is kept after."}},{id:"csv-guides",href:"/journal",added:"2026-10-29",title:(0,t.msg)("How to export your trades, firm by firm"),line:(0,t.msg)("Import a CSV > How do I export my trades?: pick futures or CFDs, your prop firm and the platform you trade on, and get numbered steps with icons, whether Liquid reads that file, and a link to their own help. 15 firms, 22 platforms."),announce:{heading:"Get your trades out of any prop firm",body:"Not sure how to export your trades? Open Import a CSV and tap How do I export my trades. Pick futures or CFDs, your prop firm and the platform you trade on, and you get the steps one by one, with a note on whether Liquid reads that file."}},{id:"trade-merge",href:"/journal",added:"2026-10-29",title:(0,t.msg)("Merge trades"),line:(0,t.msg)("Journal > Merge, next to Filters: pick the trades that were one position (partials and add-ons a broker or a CSV split into rows) and tap Merge. One trade: the P&L and contracts added up, the average entry and exit, the first entry and the last exit, and every note, chip and picture kept. Undo for 10 seconds."),announce:{heading:"Merge trades into one",body:"Took partials or added on, and your broker or CSV gave you three trades? Tap Merge next to Filters in your journal, pick them, and they become one trade with the P&L, the contracts and your notes all together. Undo is there for 10 seconds."}},{id:"share-plus",href:"/journal",added:"2026-10-29",title:(0,t.msg)("Share to Community, Day card chart and all trades, R as a unit"),line:(0,t.msg)("The share window has a big Share to Community button above Video, GIF and Photo: the card's video goes into Community's post window with tags, a $ticker and who sees it. The Day card picks which of its trades is on the chart, with the timeframe, or lists all its trades. Format > Show picks $, % or R."),announce:{heading:"Share your cards straight to Community",body:"Tap Share on a trade, a day or a week and post the card's video to Community in one step, with your words, tags and the ticker. On the daily card you pick which trade is on the chart, or list every trade you took. And a card can now show your result in R instead of dollars."}},{id:"swing",href:"/journal/new",added:"2026-10-29",title:(0,t.msg)("Swing trades: opened and closed"),line:(0,t.msg)("Pick Swing in Log Trade and a trade gets two days, Opened and Closed, with how long you held it; any trade can close on another day. The P&L counts on the close day. Advanced adds a thesis, an invalidation price on the chart and a day on each partial. Hold time in Analytics counts days. Log settings sets the type Log Trade opens on."),announce:{heading:"Swing trades get two dates",body:"Pick Swing when you log a trade and you get two dates: the day you opened it and the day you closed it, and the journal shows how long you held it. The P&L counts on the day you closed it. In Advanced you can write your thesis, set an invalidation price that shows on the chart, and give each partial its own day. Hold time in Analytics now goes past a day, and Log settings lets you open Log Trade on Swing."}},{id:"share-15m",href:"/journal",added:"2026-10-25",title:(0,t.msg)("15-minute line on share cards"),line:(0,t.msg)("The share card chart gets a 15 min timeframe next to 1 sec, 1 min and 5 min, and a trade held 3 hours or more opens on it."),announce:{heading:"A 15-minute line on your share cards",body:"Swing trades look right now: the chart on your share card has a 15 min timeframe next to 1 sec, 1 min and 5 min, and a trade you held 3 hours or more opens on it by itself."}},{id:"plan-downgrade",href:"/settings",added:"2026-10-25",title:(0,t.msg)("Switch from Apex to Prestige"),line:(0,t.msg)("Apex members can switch to Prestige in Settings: Apex stays until the paid month ends, then Prestige starts. Keep Apex undoes it."),announce:{heading:"Switch from Apex to Prestige",body:"You can now move from Apex to Prestige in Settings > Subscription. You keep Apex until the month you paid for ends, then Prestige starts at its price. Nothing is refunded or charged twice, and Keep Apex undoes it any time before then."}},{id:"score-v2",href:"/dashboard",added:"2026-10-25",title:(0,t.msg)("New Liquid Score"),line:(0,t.msg)('The Liquid Score reads the last 30 days (or all time, by a switch), moves every day with "+N since yesterday", scores break-even at 40, Consistency as the prop firm rule, and Discipline from how you journal: trades every weekday 80, a daily journal 90, a weekly review 100.'),announce:{heading:"Your Liquid Score now moves with you",body:"The Liquid Score reads your last 30 days by default (switch to all time on the card) and shows how much it moved since yesterday. Consistency now works like a prop firm rule: your best day against your profit. Discipline comes from how you journal: log your trades with a note every weekday for 80, add a daily journal for 90, and a weekly review for 100. Weekends never count."}},{id:"live-cards",href:"/propfirm",added:"2026-10-25",title:(0,t.msg)("Live account cards"),line:(0,t.msg)("Live broker accounts in the plan cards' look: Add a live account in two steps (broker tiles, then one card where you type the starting balance), and each live account on Prop firms as a card with its balance, growth, curve and money in and out on the back."),announce:{heading:"Your live accounts, redone",body:"Live broker accounts now look like your prop cards. Adding one takes two steps: pick the broker, then type the starting balance on one card. On Prop firms each live account is a card with its balance, growth and curve; turn it over to add a deposit or a withdrawal."}},{id:"weekly-v2",href:"/weekly",added:"2026-10-25",title:(0,t.msg)("Weekly report card"),line:(0,t.msg)("The weekly journal as a report card: your week graded in six areas from what you already logged, a tap to agree or change a grade, one fix for next week from your lowest grade, and past weeks as report cards."),announce:{heading:"Your week, graded for you",body:"The weekly journal no longer asks you to type. It grades your week in six areas (planning, rules, patience, risk, head and execution) from your trades and daily journal. Tap Fair or give your own grade, pick one fix for next week, and next week your trades say if you kept it."}},{id:"date-picker",href:"/journal/new",added:"2026-10-25",title:(0,t.msg)("One calendar for every date"),line:(0,t.msg)("Every date you pick (journal, trades, prop firms, Analytics) opens one clean calendar: tap a day and it is set, Today and Yesterday one tap away, tap the month to jump months and years."),announce:{heading:"Picking a date is easier now",body:"Every date field in Liquid now opens the same clean calendar. Tap a day and it is set, no OK button. Today and Yesterday are one tap away, and tapping the month lets you jump to any month or year in two taps. On a phone, swipe sideways to change month."}},{id:"daily-v2",href:"/daily",added:"2026-10-25",title:(0,t.msg)("New Daily journal"),line:(0,t.msg)("Daily journal, idea A from the members' vote: today as Plan, Trade, Review in taps, past days as cards that open as a sheet, the streak, the month, what your days say, a lesson from you and this week."),announce:{heading:"Your Daily journal, rebuilt",body:"Today now sits on top as three steps: plan in a few taps, your trades land by themselves, review in two minutes. Past days are cards, and on the right you get your streak, what your days say about your P&L, and one of your own lessons each day."}},{id:"log-split",href:"/propfirm",added:"2026-10-25",title:(0,t.msg)("Log eval or funded"),line:(0,t.msg)('The plan cards in Add account get one button for both: Log eval top left, Log funded bottom right, a slash with "or" between them.'),announce:{heading:"Log an eval or a funded account in one tap",body:"On the plan cards in Add account, one button now does both: Log eval on the left, Log funded on the right."}},{id:"account-cards",href:"/propfirm",added:"2026-10-25",title:(0,t.msg)("Account cards"),line:(0,t.msg)("Your evaluation and funded cards on Prop firms in the plan cards' look: the firm's colour and mark, Rules on the back, Update balance and Log payout open on the card."),announce:{heading:"New: your prop accounts, redone",body:"Your evaluation and funded cards now look like the plan cards: the firm's colour, the balance up front, the rules on the back of the card. Update balance and Log payout open right on the card."}},{id:"plan-picker",href:"/propfirm",added:"2026-10-24",title:(0,t.msg)("Plan cards"),line:(0,t.msg)("Add account shows the firm's plans as cards: rule sets on top, every size side by side, the rules on the card, Funded details turns it over, Log eval adds them."),announce:{heading:"New: pick your account like on the firm's site",body:"Adding a prop account now shows the firm's plans as cards. Pick the rule set on top, swipe through the sizes, turn a card over for the funded rules, and log as many evaluations as you bought in one go."}},{id:"wizard-layer",href:"/propfirm",added:"2026-10-24",title:(0,t.msg)("Add account as a window"),line:(0,t.msg)("Add account opens from the middle as a rounded window, like an account's Details and Appearance: the Prop firm or Live choice, the prop wizard and the live account wizard."),announce:{heading:"Adding a prop account, smoother",body:"Adding an account now opens as a rounded window, like your account details do: pick Prop firm or Live, then the same steps as before."}},{id:"strategy-v2",href:"/strategy",added:"2026-10-24",title:(0,t.msg)("New strategy cards"),line:(0,t.msg)("Strategies become compact cards: picture, numbers, setup chips. Tap one for the whole strategy in a sheet; Edit and New Strategy open as a sheet."),announce:{heading:"New: your strategies, redesigned",body:"Each strategy is now a compact card with its picture, its numbers and its setup. Tap it to see the whole strategy, and edit it in a sheet that rises from the bottom."}},{id:"more-layers",href:"/dashboard",added:"2026-10-24",title:(0,t.msg)("More layers"),line:(0,t.msg)("Report, Suggest, Keyboard shortcuts, an insight's detail and the install guide open as the sheet that rises from the bottom; on a phone, Are you sure becomes a small sheet with two big buttons."),announce:{heading:"Smoother windows everywhere",body:"Report a problem, Suggest a feature, keyboard shortcuts, insight details and the install guide now rise from the bottom like Log Trade does. On your phone, every Are you sure is a small sheet with two big buttons, right where your thumb is."}},{id:"pct-pnl",href:"/dashboard",added:"2026-10-24",title:(0,t.msg)("P&L as % of the account"),line:(0,t.msg)("The P&L calendars switch between $, R and %, and the share cards between $ and %: +$500 on a 50K account is +1%."),announce:{heading:"New: your P&L in %",body:"The P&L calendar now switches between $, R and %, and your share cards can show % instead of dollars. +$500 on a 50K account is +1%. The size comes from your prop or live account, or one size you set for the rest."}},{id:"affiliate-kit",href:"/settings",added:"2026-10-23",quiet:!0,title:(0,t.msg)("Affiliate window and promo kit"),line:(0,t.msg)("Affiliates get one window: overview, a promo kit of cards with their real code (40% for good, 50% and 60% sales, locked until they open), earnings, Message Trav. Admin > Affiliates gets Sales.")},{id:"prop-costs",href:"/propfirm",added:"2026-10-22",title:(0,t.msg)("Compare payouts to spend"),line:(0,t.msg)("What your prop accounts cost against what they paid: the bar under your accounts, Costs in each account, the AI knows it."),announce:{heading:"New: Compare payouts to spend",body:"One bar under your prop accounts now shows what your evals and resets cost against what your payouts brought in. Every account has its own Costs tab, and the prop firm AI knows the numbers."}},{id:"page-motion",href:"/dashboard",added:"2026-10-28",title:(0,t.msg)("Page motion"),line:(0,t.msg)("Pages fade in and their cards rise one after another; the Cumulative P&L draws itself from your first trade to your last; the Analytics calendar fades in; the Desk and Plan slide in and out smoothly."),announce:{heading:"Liquid moves when you switch pages",body:"Every page fades in and its cards rise in turn. Your Cumulative P&L draws itself from your first trade to your last, the Analytics calendar fades in, and the Desk and Plan slide smoothly both ways."}},{id:"liquid-motion",href:"/propfirm",added:"2026-10-22",title:(0,t.msg)("Liquid motion"),line:(0,t.msg)("Every switch slides on a raised thumb, and popups, menus and the Wallet close smoothly instead of vanishing."),announce:{heading:"Liquid moves smoother",body:"Switches slide on a raised thumb instead of jumping, and windows and menus close softly instead of vanishing. Same app, it just feels calmer."}},{id:"session-stage",href:"/",added:"2026-10-22",title:(0,t.msg)("Website: the five screens, rebuilt"),line:(0,t.msg)("The landing page's five screens: a planet carries the dashboard you wipe clear, then each screen rises and snaps onto the last; the Coach opens out of the Ring over the shining earth.")},{id:"dock-hover",href:"/",added:"2026-10-22",title:(0,t.msg)("Website: the Dock that magnifies"),line:(0,t.msg)("In Keep Liquid in your Dock, the icon under your mouse grows like a real Mac Dock, its neighbours make room and its name shows above it.")},{id:"website-aura",href:"/",added:"2026-10-30",title:(0,t.msg)("Website: the aura behind the Dock"),line:(0,t.msg)("Behind Keep Liquid in your Dock, soft white light glows behind the tiles and the Dock, with a fine grain. A still picture, nothing moves.")},{id:"firms-all",href:"/",added:"2026-10-23",title:(0,t.msg)("Website: see every prop firm"),line:(0,t.msg)("Under the firm rails, one line with how many firms and brokers we track, and a See all button that opens every one at once.")},{id:"second-layers",href:"/journal",added:"2026-10-23",title:(0,t.msg)("Second layers"),line:(0,t.msg)("Log Trade, Edit, Quick Log, the daily and weekly editors, the calendar day, the Wallet and the journal filters open as layers; journal chips get a colour dot."),announce:{heading:"Logging got faster",body:"Log Trade, Quick Log and Edit now open over the page you are on, as a sheet that rises from the bottom. Save and it slides away, your trade already in the journal; close it and your draft waits for you. Import CSV sits right in Log Trade, the Wallet drops in from the top, and the chips on your journal cards are cleaner."}},{id:"copy-links",href:"/propfirm",added:"2026-10-22",title:(0,t.msg)("Copy trade on the cards"),line:(0,t.msg)("Copy-trade groups move onto the cards: a bar on top, the leader ringed, dotted links between the copies."),announce:{heading:"Copy trade, right on your cards",body:"Your copy-trade groups now live on the account cards: a bar on top, the leader ringed, and dotted links between the accounts that copy it."}},{id:"journal-notes",href:"/daily",added:"2026-10-23",title:(0,t.msg)("Notes on every day and week"),line:(0,t.msg)("A Notes section at the end of each daily entry and each week, typed straight in and saved as you type. Every plan; the AI reads it."),announce:{heading:"New: Notes on every day and week",body:"Every daily entry and every week now ends with a Notes section for anything that does not fit the plan or the review. Type straight in and it saves as you type, on every plan. On Apex, the AI coach reads your notes too."}},{id:"bg-rotate",href:"/settings",added:"2026-10-24",title:(0,t.msg)("Rotate backgrounds"),line:(0,t.msg)("Up to six backgrounds take turns in one Look: videos play to their end, pictures stay 30 seconds. Shuffle, a Next button, and theme codes carry the list."),announce:{heading:"New: Rotate your backgrounds",body:"Pick up to six backgrounds and Liquid plays them in turn, like a screensaver: each video plays to its end, each picture stays 30 seconds, then the next one fades in. Shuffle mixes the order, Next skips one, and your Look keeps its colours the whole time. A saved Look or a theme code brings the list with it."}},{id:"cm-wide",href:"/community",added:"2026-10-24",title:(0,t.msg)("Community: a wider layout"),line:(0,t.msg)("On a wide screen the Community bar shows its names, Post is one big button and your chats sit under Chats."),announce:{heading:"Community fills your screen",body:"On a wide screen the Community bar now shows the name of every place, with Post as one big button at the top and your chats under it. On a smaller window, hover an icon and its name slides out. Your posts keep the same width, so they read the same."}},{id:"cm-clean",href:"/community",added:"2026-11-10",title:(0,t.msg)("Community: the clean look"),line:(0,t.msg)("Posts in one column with thin lines between them, a plain bar, and blue for the open tab, links, tags and anything new. Glass and Ink both. On a phone: one thin top row, and search lives in Explore."),announce:{heading:"Community has a cleaner look",body:"Posts now sit in one column with a thin line between them, without a card around each one. The bar is plain icons with their names, and blue marks the tab you are on, links, $tickers, #tags and anything new. Glass and Ink both have it. On a phone the top is one thin row, and search lives in Explore."}},{id:"cm-search",href:"/community",added:"2026-10-24",title:(0,t.msg)("Community: search, and the chat in the middle"),line:(0,t.msg)("Search in Messages, Crews and Notifications. On a wide screen the chat opens in the middle and your chats list sits on the right."),announce:{heading:"Search Messages, Crews and Notifications",body:"Each of them now has a search box at the top. In Messages, type a name to find a chat or someone new to message. In Crews, find any crew by its name or tag. In Notifications, find who liked, replied or followed. On a wide screen your chat opens in the middle, with your chats on the right."}},{id:"cm-typing",href:"/community",added:"2026-10-24",title:(0,t.msg)("Community: see when someone is typing"),line:(0,t.msg)('Three dots in the chat, "typing…" in your chat list and a small badge on their face on the left bar while they write; their message appears the moment they send.'),announce:{heading:"See when someone is typing",body:"When someone is writing to you in Community, three dots show in the chat, your chat list says typing…, and their face on the left bar gets a small badge. The moment they send, their message takes the dots' place, no waiting."}},{id:"dm-media",href:"/community",added:"2026-10-26",title:(0,t.msg)("Community: pictures and GIFs in messages"),line:(0,t.msg)("Send a photo (pick one, take one or paste it) or a GIF from the same picker as posts, with words if you like. Only the two of you can open the photo; a request stays words until it is accepted."),announce:{heading:"Pictures and GIFs in messages",body:"You can now send a photo or a GIF in a Community message, with words if you like. Pick a photo, take one on your phone or paste it in; GIFs come from the same picker as posts, favourites included. Only the two of you can open a photo, and a message request stays words until it is accepted."}},{id:"card-trades",href:"/community",added:"2026-10-26",title:(0,t.msg)("Community: firms and markets on your card"),line:(0,t.msg)("Your card on the right shows two rows: the prop firms you picked, as their logos, and the markets you trade most, each with its icon and name.")},{id:"post-photos",href:"/community",added:"2026-10-26",title:(0,t.msg)("Community: up to 20 pictures in a post"),line:(0,t.msg)("Prestige and Apex put up to 20 pictures in one post, Essential up to 10 (was 4). Five or more show as a gallery you swipe, with arrows on a computer."),announce:{heading:"Up to 20 pictures in a post",body:"A Community post now takes up to 20 pictures on Prestige and Apex, and up to 10 on Essential. Five or more show as a gallery: swipe on your phone, use the arrows on a computer, and tap any picture to see it full size."}},{id:"notrade-v2",href:"/journal/new",added:"2026-10-28",title:(0,t.msg)("No-trade days, Advanced, and short and long bias"),line:(0,t.msg)("A no-trade day gets Advanced: the setup you watched, why you did not trade, how you felt and the move you missed, with its own card in Analytics. Your plan adds short-term and long-term bias."),announce:{heading:"Learn from the days you did not trade",body:"Log a no-trade day in Advanced to note the setup you watched, why you stayed out, how you felt and the move you missed. Analytics now has a No-trade days card that shows your top reasons and the setup you miss most. Your daily plan also takes a short-term and a long-term bias next to the day's."}},{id:"connect-partners",href:"/dashboard?wallet=connect",added:"2026-10-28",title:(0,t.msg)("Wallet: Replica Copier on top, connections under Coming soon"),line:(0,t.msg)("Wallet > Connect opens with a Replica Copier partner card: Visit Replica Copier for everyone, Connect for the people you unlock in Admin > Connections. TopstepX and Rithmic wait under Coming soon and open in place for you.")},{id:"tradovate-sync",href:"/dashboard?wallet=connect",added:"2026-11-09",title:(0,t.msg)("Wallet: Tradovate auto sync"),line:(0,t.msg)("Connect Tradovate in Wallet > Connect: sign in once and every fill lands in your journal by itself, fees included, filed into the right prop account. Free on every plan.")},{id:"post-video",href:"/community",added:"2026-10-30",title:(0,t.msg)("Community: videos in posts"),line:(0,t.msg)("Prestige and Apex add one video to a post with the new video button: up to 60 seconds and 100 MB. It shows its first frame in the feed and plays when you tap it. Essential sees the button with a lock."),announce:{heading:"Post videos in Community",body:"Prestige and Apex can now add a video to a Community post with the new video button next to the picture button. Pick a clip up to 60 seconds and 100 MB: it shows its first frame in the feed and plays with sound when someone taps it."}},{id:"sub-liquid40",href:"/settings?section=subscription",added:"2026-11-02",title:(0,t.msg)("Subscription: LIQUID price on Prestige and Apex"),line:(0,t.msg)("The plan list strikes the list price and shows the price with LIQUID beside it, in the plan colour, on Monthly. Upgrade opens the checkout with LIQUID on. Members who already pay see their plan as before.")},{id:"live-notes",href:"/study",added:"2026-11-11",title:(0,t.msg)("Shared notes: everyone types at once"),line:(0,t.msg)("A note you share runs live: everyone in it types at the same time, the edits merge, and you see each person's cursor with their name."),announce:{heading:"Shared notes are live",body:"A note you share in the Study Room now runs live. Everyone in it can type at the same time, nothing waits for a turn, and you see where each person is typing with their name on the cursor."}},{id:k,href:"/analytics",added:"2026-11-26",title:(0,t.msg)("Fees-only trades count as break-even"),line:(0,t.msg)("A trade that closed at its entry and lost only its fees is break-even now: not a loss, not in a loss streak, and left out of your win rate."),announce:{heading:"Break-even trades fixed",body:"A trade you closed at your entry price used to count as a loss because of its fees. It now counts as break-even: it is left out of your win rate and never starts a loss streak."}},{id:S,href:"/dashboard",added:"2026-11-26",title:(0,t.msg)("Twelve new LIQUID originals"),line:(0,t.msg)("Nine nature pictures, a samurai and two words pictures join the originals, in 3D or with a hover of their own, including a new mist."),announce:{heading:"Twelve new originals",body:"Nine nature pictures, a samurai in the grass and two words pictures are in Appearance > Background. The peaks, the dunes and the penguin move in 3D; the others answer your cursor with mist, clouds, water or ink."}},{id:A,href:"/journal",added:"2026-11-26",title:(0,t.msg)("Eight pictures for share cards"),line:(0,t.msg)("Eight still pictures join the eight videos under Liquid when you pick a share card background: two cars from Porsche and one Lamborghini, peaks, a shepherd and a handwritten line."),announce:{heading:"Eight new share card pictures",body:"Open any trade, press Share and pick Background > Liquid: eight still pictures now sit beside the eight videos."}}];P.map(e=>e.id);let T=()=>!1;e.s(["BLUE_COUPON_PREVIEW",0,i,"CANCEL_FLOW_PREVIEW",0,l,"CARD_GLASS_PREVIEW",0,g,"CHART_LOOK_PREVIEW",0,u,"COMPACT_PHONE_PREVIEW",0,h,"CUSTOM_THEME_PREVIEW",0,f,"DOWNLOAD_RING_PREVIEW",0,m,"FEE_SCRATCH_PREVIEW",0,k,"LOOK_LIVE_PREVIEW",0,w,"MEMBER_TOUR_PREVIEW",0,b,"MODS_PREVIEW",0,v,"ORIGINALS_5_PREVIEW",0,S,"PREVIEWS",0,P,"PROFILE_QUESTIONS_PREVIEW",0,c,"REWARD_TICKETS_PREVIEW",0,n,"SHARE_FORMAT_PREVIEW",0,y,"SHARE_PERIODS_PREVIEW",0,p,"SHARE_PICS_PREVIEW",0,A,"SPEED_PASS_PREVIEW",0,s,"STACK_DEAL_PREVIEW",0,d,"TRIAL_SWITCH_PREVIEW",0,r,"XMAS_APP_PREVIEW",0,o,"XMAS_PRESENTS_PREVIEW",0,a,"previewOn",0,function(e){return T(e)},"setPreviewGate",0,function(e){T=e}])}]);

//# debugId=32858c1a-5146-b2c9-0a37-4f70d557a660